    <script type="module">
        /* 更新进度条辅助函数 */
        function updateProgressBar(barId, valueId, rawValue, min = 0, max = 100, color = '#b33a3a') {
            const numericValue = parseFloat(rawValue);
            if (!isNaN(numericValue)) {
                const clampedValue = _.clamp(numericValue, min, max);
                const percentage = max - min === 0 ? 0 : ((clampedValue - min) / (max - min)) * 100;

                $(`#${valueId}`).text(clampedValue);
                $(`#${barId}`).css({
                    width: `${percentage}%`,
                    backgroundColor: color
                });
            } else {
                $(`#${valueId}`).text(rawValue);
            }
        }

        /* 填充状态栏数据 */
        function populateCharacterData() {
            try {
                const all_variables = getAllVariables();
                const characterData = all_variables.stat_data;

                if (!characterData) {
                    $('#status-card').html("<div class='error-tip'>无法加载状态数据</div>");
                    return;
                }

                /* 光阴 */
                $('#current-era').text(_.get(characterData, '光阴.纪年', 'N/A'));
                $('#current-hour').text(_.get(characterData, '光阴.时辰', 'N/A'));

                /* 谢必安 */
                updateProgressBar(
                    'xiebian-bond-bar',
                    'xiebian-bond-value',
                    _.get(characterData, '谢必安.羁绊', 0),
                    0, 100, '#b33a3a'
                );
                $('#xiebian-status').text(_.get(characterData, '谢必安.境况', 'N/A'));
                $('#xiebian-mood').text(_.get(characterData, '谢必安.心绪', 'N/A'));
                $('#xiebian-voice').text(_.get(characterData, '谢必安.心声', 'N/A'));

                /* 范无咎 */
                updateProgressBar(
                    'fanwujiu-bond-bar',
                    'fanwujiu-bond-value',
                    _.get(characterData, '范无咎.羁绊', 0),
                    0, 100, '#e2673f'
                );
                $('#fanwujiu-status').text(_.get(characterData, '范无咎.境况', 'N/A'));
                $('#fanwujiu-mood').text(_.get(characterData, '范无咎.心绪', 'N/A'));
                $('#fanwujiu-voice').text(_.get(characterData, '范无咎.心声', 'N/A'));
            } catch (error) {
                $('#status-card').html(`<div class='error-tip'>状态栏加载出错: ${error.message}</div>`);
            }
        }

        /* 切换标签，并联动整卡的明暗主题 */
        function switchTab(role) {
            $('.tab-button').removeClass('active');
            $(`.tab-button[data-role="${role}"]`).addClass('active');

            $('.tab-panel').removeClass('active');
            $(`#tab-content-${role}`).addClass('active');

            const $card = $('#status-card');
            if (role === 'fanwujiu') {
                $card.removeClass('theme-light').addClass('theme-dark');
            } else {
                $card.removeClass('theme-dark').addClass('theme-light');
            }
        }

        /* 初始化 */
        async function init() {
            await waitGlobalInitialized('Mvu');
            populateCharacterData();

            $('.tab-button').on('click', function () {
                switchTab($(this).data('role'));
            });
        }

        $(errorCatched(init));
    </script>
