                            '境况': '当街拿获行窃现行的{{user}}，一路疾追将她整个人揽进怀里',
                            '心绪': '抓着人赃并获的痛快尚未褪去，却被她这一撞搅得心绪莫名发烫，耳根泛红',
                            '心声': '这丫头手法生涩得很，倒不像惯犯——只是这般撞进怀里，怎的我这心跳比追贼时还乱三分'
                        }
                    }
                }
            ];

            var CN_NUM = ['一', '二', '三', '四', '五', '六', '七', '八', '九', '十'];
            var TITLE_RE = /\[\[title:\s*(.*?)\s*\]\]/;
            var DESC_RE = /\[\[desc:\s*(.*?)\s*\]\]/;

            function renderError(message) {
                $('#opening-list').html('<div class="error-tip">' + message + '</div>');
            }

            async function renderMenu() {
                if (typeof getChatMessages !== 'function' || typeof setChatMessages !== 'function') {
                    renderError('未检测到「酒馆助手」扩展。<br>请安装并启用后再打开此卡。');
                    return;
                }

                try {
                    var messages = await getChatMessages('0', { include_swipe: true });
                    var swipes = messages && messages[0] && messages[0].swipes;

                    if (!swipes || swipes.length <= 1) {
                        $('#opening-list').html('<div class="empty-tip">暂无可选的开场白。</div>');
                        return;
                    }

                    var $list = $('#opening-list');
                    $list.empty();

                    for (var i = 1; i < swipes.length; i++) {
                        var text = swipes[i];
                        var titleMatch = text.match(TITLE_RE);
                        var descMatch = text.match(DESC_RE);
                        var title = titleMatch ? titleMatch[1].trim() : ('第 ' + i + ' 篇');
                        var desc = descMatch ? descMatch[1].trim() : '尚无简介。';
                        var mark = CN_NUM[i - 1] || String(i);

                        var $item = $(
                            '<div class="opening-item" data-swipe="' + i + '">' +
                                '<div class="opening-mark">' + mark + '</div>' +
                                '<div class="opening-body">' +
                                    '<div class="opening-title"></div>' +
                                    '<div class="opening-desc"></div>' +
                                '</div>' +
                                '<div class="opening-hint">点选 ›</div>' +
                            '</div>'
                        );
                        $item.find('.opening-title').text(title);
                        $item.find('.opening-desc').text(desc);
                        $item.on('click', function () {
                            chooseOpening($(this));
                        });
                        $list.append($item);
                    }
                } catch (error) {
                    renderError('开场白读取失败：' + error.message);
                }
            }

            async function chooseOpening($item) {
                var swipeId = parseInt($item.data('swipe'), 10);
                if (!swipeId) {
                    return;
                }

                $('.opening-item').addClass('is-loading');

                try {
                    await setChatMessages([{ message_id: 0, swipe_id: swipeId }]);

                    var preset = OPENINGS[swipeId - 1];
                    if (preset && typeof replaceVariables === 'function') {
                        var payload = {
                            stat_data: preset.initvar,
                            display_data: preset.initvar,
                            delta_data: {},
                            schema: {},
                            initialized_lorebooks: {}
                        };
                        /* MVU 实际从"楼层(message)"作用域读取当前 swipe 的 stat_data，必须先切换 swipe 再写入这里 */
                        await replaceVariables(payload, { type: 'message', message_id: 0 });
                        /* 同步一份到聊天作用域，兼容部分直接读取 type:'chat' 的脚本 */
                        if (typeof insertOrAssignVariables === 'function') {
                            await insertOrAssignVariables(payload, { type: 'chat' });
                        }
                    }
                } catch (error) {
                    $('.opening-item').removeClass('is-loading');
                    renderError('切换开场白失败：' + error.message);
                }
            }

            $(renderMenu);
        })();
    </script>
</head>
